suppressPackageStartupMessages(library(zoo))
options(digits = 7)
show <- function(v) {
  if (is.logical(v) && length(v) == 1) {
    cat(if (isTRUE(v)) "TRUE\n" else "FALSE\n")
  } else if (is.zoo(v)) {
    show(coredata(v))
    show(index(v))
  } else {
    cat(paste(vapply(as.numeric(v), function(a) if (is.na(a)) "NA" else sprintf("%.16g", a), ""), collapse = " "), "\n", sep = "")
  }
}
show(aggregate(zoo(c(1, NA, 3), c(1, 2, 3)), c(1, 1, 2), sum, na.rm = TRUE))
